<script>
    document.addEventListener('DOMContentLoaded', function () { const input = document.querySelector('[data-agent-search]'); if (!input) return; const cards = [...document.querySelectorAll('[data-agent-card]')]; const empty = document.querySelector('[data-agent-empty]'); input.addEventListener('input', function () { const query = this.value.trim().toLowerCase(); let visible = 0; cards.forEach(card => { const match = !query || card.dataset.agentSearchText.includes(query); card.hidden = !match; if (match) visible++; }); if (empty) empty.hidden = visible !== 0; }); });
</script>

